class Solution {
public:
    long long maxScore(vector<int>& nums, int x) {
        long long best[2] = {nums[0], nums[0]};
        best[(nums[0] & 1) ^ 1] -= x;
        long long ans = nums[0];
        for (size_t i = 1; i < nums.size(); i++) {
            int p = nums[i] & 1;
            long long cur = nums[i] + max(best[p], best[p ^ 1] - (long long)x);
            best[p] = max(best[p], cur);
            ans = max(ans, cur);
        }
        return ans;
    }
};

