class Solution {
    public long maxScore(int[] nums, int x) {
        long[] best = {nums[0], nums[0]};
        best[(nums[0] & 1) ^ 1] -= x;
        long ans = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int p = nums[i] & 1;
            long cur = nums[i] + Math.max(best[p], best[p ^ 1] - (long) x);
            best[p] = Math.max(best[p], cur);
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

