var maxScore = function(nums, x) {
    const best = [nums[0], nums[0]];
    best[(nums[0] & 1) ^ 1] -= x;
    let ans = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const p = nums[i] & 1;
        const cur = nums[i] + Math.max(best[p], best[p ^ 1] - x);
        best[p] = Math.max(best[p], cur);
        ans = Math.max(ans, cur);
    }
    return ans;
};
